/**
 * Golden contract for the SM-18 format-write port follow-up on
 * `info/RepetitionHistory.dat` (sm18-re gitlab #46).
 *
 * The fixture `test/fixtures/sm18-port-format-write-rephistory.json` is a
 * byte-for-byte mirror of
 * `sm18-re:tests/fixtures/port-format-write-rephistory.json`, generated by
 * `sm18-re:scripts/export-port-format-write-rephistory-fixture.py`. The lane
 * re-copies the mirror on every fixture change so sm18-re's gate catches
 * drift on either side.
 *
 * This file is brief-writer owned. The lane implements the new export in
 * `src/sm18-format-write.ts`:
 *
 *   writeRepetitionHistory(records: RepetitionHistoryRawRecord[]): Uint8Array
 *
 * Transliteration of `smfmt.repetition_history.write`: the file has no
 * header, so the TS writer takes only `records` and concatenates each
 * record's bytes. The record carrier mirrors the `ComponRawRecord` carrier
 * from the v1 writer because `parseRepetitionHistory` deliberately drops the
 * 20 unprojected bytes per record (the 6-byte gap between `interval_days`
 * and `repetition_date`, and the 14-byte trailer after `grade`), so a
 * typed-record encoder cannot reproduce the stored bytes from the read-side
 * projection alone. A typed encoder is a separate follow-up once more of the
 * record geometry is defended; this lane ships the bytes-in / bytes-out
 * contract the Python reference also ships.
 *
 * Each file in the fixture carries `expected_bytes_b64` and a `records`
 * array of `{raw_b64}`. The harness feeds the records into
 * `writeRepetitionHistory` and asserts the output byte sequence equals
 * `expected_bytes_b64`.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-write-rephistory.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-write.ts"].join("/");

interface RepetitionHistoryRawRecord {
  raw_b64: string;
}

interface FixtureFile {
  collection: string;
  path: string;
  byte_length: number;
  record_count: number;
  records: RepetitionHistoryRawRecord[];
  expected_bytes_b64: string;
}

interface Fixture {
  schema: number;
  scope: string[];
  max_records_per_file: number;
  excluded_oversize: string[];
  files: FixtureFile[];
}

interface PortModule {
  writeRepetitionHistory: (
    records: RepetitionHistoryRawRecord[],
  ) => Uint8Array;
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (typeof mod?.writeRepetitionHistory !== "function") {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

function bytesEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.byteLength !== b.byteLength) return false;
  for (let i = 0; i < a.byteLength; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the rephistory scope and non-empty file set", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["repetition_history"]);
  assert.ok(fixture.files.length > 0, "at least one file is pinned");
  for (const file of fixture.files) {
    assert.equal(
      file.records.length,
      file.record_count,
      `${file.path} record_count matches records length`,
    );
    assert.equal(
      file.byte_length,
      file.record_count * 39,
      `${file.path} byte_length is 39 bytes per record`,
    );
    assert.ok(
      typeof file.expected_bytes_b64 === "string" &&
        file.expected_bytes_b64.length > 0 ||
        file.byte_length === 0,
      `${file.path} carries expected bytes (or is empty)`,
    );
  }
});

test("src/sm18-format-write.ts exports writeRepetitionHistory", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-format-write.ts does not yet export writeRepetitionHistory");
    return;
  }
  assert.equal(typeof port.writeRepetitionHistory, "function");
});

for (const file of fixture.files) {
  test(`format-write rephistory: ${file.path} rebuilds ${file.byte_length} bytes`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("src/sm18-format-write.ts does not yet export writeRepetitionHistory");
      return;
    }
    const expected = decodeBase64(file.expected_bytes_b64);
    assert.equal(
      expected.byteLength,
      file.byte_length,
      `expected byte count for ${file.path}`,
    );
    const produced = port.writeRepetitionHistory(file.records);
    assert.ok(
      bytesEqual(produced, expected),
      `${file.path} must round-trip byte for byte ` +
        `(got ${produced.byteLength} bytes, expected ${expected.byteLength})`,
    );
  });
}
